import { expect, test } from "@playwright/test";
import { mkdirSync, readFileSync } from "node:fs";
import { signInSeedUser } from "./support/auth";

test.skip(process.env.E2E_REVIEW_LIVE !== "1" || !/^http:\/\/(127\.0\.0\.1|localhost):/.test(process.env.NEXT_PUBLIC_SUPABASE_URL ?? ""), "실제 로컬 Supabase만 사용");

test("원본 파기 뒤에도 전사를 읽고 원본 재생·재추출은 차단된다", async ({ page, context, baseURL }) => {
  test.setTimeout(120_000);
  // Generated by retention-test after actual Storage deletion has passed.
  const fixture = JSON.parse(readFileSync(".vercel/review-qa/retention-fixture.json", "utf8"));
  expect(fixture.origin).toBe(new URL(process.env.NEXT_PUBLIC_SUPABASE_URL!).origin);
  expect(new URL(baseURL!).hostname).toMatch(/^(localhost|127\.0\.0\.1)$/);
  process.env.RETENTION_QA_EMAIL = fixture.email;
  process.env.RETENTION_QA_PASSWORD = fixture.password;
  const errors: string[] = [];
  page.on("pageerror", error => errors.push(error.name));
  try {
    const { supabase } = await signInSeedUser(context, baseURL!, { emailEnv: "RETENTION_QA_EMAIL", passwordEnv: "RETENTION_QA_PASSWORD" });
    const endpoint = `/api/d/${fixture.dept}/reviews/${fixture.reviewId}`;
    await page.goto(`/d/${fixture.dept}/reviews/${fixture.reviewId}`);
    await expect(page.getByLabel("구간 1 텍스트")).toHaveValue("합성 회의에서는 검토한 근거를 보존하기로 했습니다.");
    await expect(page.getByText("원본이 지워졌거나 보관 기한이 지났습니다", { exact: true })).toBeVisible();
    await expect(page.getByRole("button", { name: "원본 듣기", exact: true })).toHaveCount(0);
    await expect(page.getByRole("button", { name: "원본 다시 읽기", exact: true })).toBeDisabled();
    await expect(page.locator("audio")).toHaveCount(0);
    expect((await context.request.get(`${endpoint}/original?action=play_original`)).status()).toBe(404);
    const reextract = await context.request.post(endpoint, { data: { action: "reextract", revision: 1 } });
    expect(reextract.status()).toBe(404);
    expect((await reextract.json()).error).toBe("보관된 원본이 없거나 보존 기한이 지났습니다.");
    const review = await supabase.from("reviewed_materials").select("original_deleted_at,published_source_id").eq("id", fixture.reviewId).single();
    expect(review.error).toBeNull();
    expect(review.data?.original_deleted_at).toBeTruthy();
    const items = await supabase.from("items").select("id").eq("source_id", review.data!.published_source_id).is("deleted_at", null);
    expect(items.error).toBeNull();
    expect(items.data).toHaveLength(1);
    const evidence = "docs/verification/review-retention-2026-09-24";
    mkdirSync(evidence, { recursive: true });
    for (const width of [1440, 390]) {
      await page.setViewportSize({ width, height: 1000 });
      await expect(page.getByLabel("구간 1 텍스트")).toBeVisible();
      expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
      await page.screenshot({ path: `${evidence}/expired-original-${width}.png`, fullPage: true });
    }
    expect(errors).toEqual([]);
  } finally {
    delete process.env.RETENTION_QA_EMAIL;
    delete process.env.RETENTION_QA_PASSWORD;
    await context.clearCookies();
  }
});
